import * as fs from "fs";
import * as path from "path";
import { execFileSync } from "child_process";

/**
 * Double-click launchers for automation scripts (the AHK "double-click a .ahk"
 * experience). Generated files are COMMITTABLE: they contain no absolute paths,
 * only a path relative to the launcher itself (%~dp0 / $0) and a PATH lookup of
 * `knowhow` with an `npx` fallback.
 */

export type LauncherPlatform = "win32" | "darwin" | "linux";

export interface LauncherOptions {
  /** Absolute or relative path to the automation script. */
  script: string;
  /** Output file (only valid with a single platform; default: next to the script). */
  out?: string;
  /** Platforms to generate for (default: the current one). */
  platforms?: LauncherPlatform[];
  /**
   * Working directory the automation runs in, RELATIVE to the script's
   * directory (default "."). `.knowhow/` state (stores, regions) lives here.
   */
  cwd?: string;
  /** Windows only: also write `<name>.vbs`, which runs the .cmd with no console window. */
  vbs?: boolean;
}

export interface GeneratedLauncher {
  platform: LauncherPlatform;
  file: string;
  content: string;
  executable: boolean;
}

export function parsePlatforms(spec: string | undefined): LauncherPlatform[] {
  if (!spec) return [process.platform === "win32" ? "win32" : process.platform === "darwin" ? "darwin" : "linux"];
  const map: Record<string, LauncherPlatform[]> = {
    win: ["win32"], win32: ["win32"], windows: ["win32"],
    mac: ["darwin"], macos: ["darwin"], darwin: ["darwin"],
    linux: ["linux"],
    all: ["win32", "darwin", "linux"],
  };
  const out: LauncherPlatform[] = [];
  for (const part of spec.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean)) {
    const m = map[part];
    if (!m) throw new Error(`Unknown platform "${part}" (use win32, darwin, linux, all; comma separated).`);
    for (const p of m) if (!out.includes(p)) out.push(p);
  }
  return out;
}

const SCRIPT_EXT = /\.(?:ts|js|mts|cts|khs)$/i;

/**
 * Launchers interpolate the script filename and cwd into cmd/bash/VBScript
 * source. Rather than trying to escape for three different shells, only allow
 * characters that are inert in all of them (no quotes, %, !, ^, &, |, <, >, $,
 * backticks, backslashes in names, newlines, ...). A crafted filename or
 * --cwd would otherwise become command injection when the launcher is
 * double-clicked.
 */
const SAFE_NAME = /^[A-Za-z0-9 ._+@,=()-]+$/;
const SAFE_REL_PATH = /^[A-Za-z0-9 ._+@,=()\/-]+$/;

export function assertSafeLauncherName(name: string, what = "Script filename"): void {
  if (!SAFE_NAME.test(name) || name === "." || name === "..") {
    throw new Error(
      `${what} "${name}" contains characters that are unsafe in generated launchers. ` +
        "Use only letters, digits, spaces and . _ + @ , = ( ) -"
    );
  }
}

export function assertSafeLauncherCwd(cwd: string): void {
  if (!SAFE_REL_PATH.test(cwd) || cwd.startsWith("/")) {
    throw new Error(
      `--cwd "${cwd}" must be a relative path using only letters, digits, spaces and . _ + @ , = ( ) - /`
    );
  }
}

/** Normalize a relative cwd to forward slashes ("" or "." -> "."). */
function relCwd(cwd?: string): string {
  const c = (cwd ?? ".").replace(/\\/g, "/").replace(/\/+$/, "");
  const rel = c === "" ? "." : c;
  assertSafeLauncherCwd(rel);
  return rel;
}

export function windowsCmd(scriptFile: string, cwd?: string): string {
  assertSafeLauncherName(scriptFile);
  const rel = relCwd(cwd).replace(/\//g, "\\");
  const q = `"%~dp0${scriptFile}"`;
  const lines = [
    "@echo off",
    `rem Launcher for ${scriptFile} (generated by \`knowhow computer make-launcher\`; safe to commit).`,
    "rem Starts the knowhow computer host if needed, hands the automation to it, and exits.",
    "setlocal",
    `pushd "%~dp0${rel}" || exit /b 1`,
    "where knowhow >nul 2>nul",
    "if %errorlevel%==0 (",
    `  call knowhow computer run-automation ${q} --no-attach`,
    ") else (",
    `  call npx --yes @tyvm/knowhow computer run-automation ${q} --no-attach`,
    ")",
    "set RC=%errorlevel%",
    "popd",
    "rem Keep the window open only when something went wrong.",
    "if not %RC%==0 (",
    "  echo.",
    "  echo Launch failed with exit code %RC%. Is the knowhow CLI installed and the computer-use module enabled?",
    "  pause",
    ")",
    "exit /b %RC%",
    "",
  ];
  return lines.join("\r\n");
}

export function windowsVbs(cmdFile: string): string {
  assertSafeLauncherName(cmdFile, "Launcher filename");
  return [
    `' Runs ${cmdFile} with NO console window (generated by \`knowhow computer make-launcher --vbs\`).`,
    `' Trade-off: errors are invisible; use the .cmd when debugging.`,
    "Set sh = CreateObject(\"WScript.Shell\")",
    "dir = CreateObject(\"Scripting.FileSystemObject\").GetParentFolderName(WScript.ScriptFullName)",
    `sh.Run "cmd /c """ & dir & "\\${cmdFile}""", 0, False`,
    "",
  ].join("\r\n");
}

function posixScript(scriptFile: string, cwd: string | undefined, mac: boolean): string {
  assertSafeLauncherName(scriptFile);
  const rel = relCwd(cwd);
  return [
    "#!/bin/bash",
    `# Launcher for ${scriptFile} (generated by \`knowhow computer make-launcher\`; safe to commit).`,
    'DIR="$(cd "$(dirname "$0")" && pwd)"',
    '# GUI-launched shells may not have node on PATH (nvm/homebrew); pick it up if present.\n[ -s "$HOME/.nvm/nvm.sh" ] && . "$HOME/.nvm/nvm.sh" >/dev/null 2>&1\nexport PATH="/opt/homebrew/bin:/usr/local/bin:$PATH"',
    `cd "$DIR/${rel}" || exit 1`,
    "if command -v knowhow >/dev/null 2>&1; then",
    `  knowhow computer run-automation "$DIR/${scriptFile}" --no-attach`,
    "else",
    `  npx --yes @tyvm/knowhow computer run-automation "$DIR/${scriptFile}" --no-attach`,
    "fi",
    "rc=$?",
    mac
      ? '[ $rc -ne 0 ] && { echo; echo "Launch failed (exit $rc). Press return to close."; read -r _; }'
      : '[ $rc -ne 0 ] && echo "Launch failed (exit $rc)." >&2',
    "exit $rc",
    "",
  ]
    .filter((l) => l !== "")
    .join("\n") + "\n";
}

/** Pure generator (no fs writes) so it can be unit tested. */
export function buildLaunchers(opts: LauncherOptions): GeneratedLauncher[] {
  const abs = path.resolve(opts.script);
  const dir = path.dirname(abs);
  const scriptFile = path.basename(abs);
  const base = scriptFile.replace(SCRIPT_EXT, "");
  const platforms = opts.platforms?.length ? opts.platforms : parsePlatforms(undefined);
  if (opts.out && platforms.length > 1) throw new Error("--out can only be used with a single --platform.");
  const out: GeneratedLauncher[] = [];
  const target = (ext: string) => (opts.out ? path.resolve(opts.out) : path.join(dir, base + ext));
  for (const p of platforms) {
    if (p === "win32") {
      const file = target(".cmd");
      out.push({ platform: p, file, content: windowsCmd(scriptFile, opts.cwd), executable: false });
      if (opts.vbs) {
        out.push({
          platform: p,
          file: path.join(path.dirname(file), path.basename(file).replace(/\.cmd$/i, "") + ".vbs"),
          content: windowsVbs(path.basename(file)),
          executable: false,
        });
      }
    } else if (p === "darwin") {
      out.push({ platform: p, file: target(".command"), content: posixScript(scriptFile, opts.cwd, true), executable: true });
    } else {
      out.push({ platform: p, file: target(".sh"), content: posixScript(scriptFile, opts.cwd, false), executable: true });
    }
  }
  return out;
}

export function writeLaunchers(opts: LauncherOptions): GeneratedLauncher[] {
  if (!fs.existsSync(opts.script)) throw new Error(`Script not found: ${opts.script}`);
  const launchers = buildLaunchers(opts);
  for (const l of launchers) {
    fs.mkdirSync(path.dirname(l.file), { recursive: true });
    fs.writeFileSync(l.file, l.content);
    if (l.executable) fs.chmodSync(l.file, 0o755);
  }
  return launchers;
}

// ── Windows file-type association (HKCU only, no admin) ─────────────────────

export const DEFAULT_FILETYPE_EXT = ".khs";
const PROG_ID = "Knowhow.Automation";

export function normalizeExt(ext?: string): string {
  const e = (ext || DEFAULT_FILETYPE_EXT).trim();
  const withDot = e.startsWith(".") ? e : "." + e;
  if (!/^\.[A-Za-z0-9_.-]+$/.test(withDot)) throw new Error(`Invalid extension: ${ext}`);
  return withDot;
}

/** `reg.exe` argument vectors that (un)register the extension under HKCU\Software\Classes. */
export function registerFiletypeCommands(ext: string, unregister = false): string[][] {
  const e = normalizeExt(ext);
  const root = "HKCU\\Software\\Classes";
  if (unregister) {
    return [
      ["delete", `${root}\\${e}`, "/f"],
      ["delete", `${root}\\${PROG_ID}`, "/f"],
    ];
  }
  // `call knowhow` (a .cmd shim); the console closes as soon as the host has taken over.
  const open = `cmd.exe /d /c call knowhow computer run-automation "%1" --no-attach`;
  return [
    ["add", `${root}\\${e}`, "/ve", "/d", PROG_ID, "/f"],
    ["add", `${root}\\${PROG_ID}`, "/ve", "/d", "Knowhow automation script", "/f"],
    ["add", `${root}\\${PROG_ID}\\shell\\open\\command`, "/ve", "/d", open, "/f"],
  ];
}

export function registerFiletype(
  ext: string | undefined,
  opts: { unregister?: boolean; dryRun?: boolean } = {}
): string[] {
  const cmds = registerFiletypeCommands(normalizeExt(ext), opts.unregister);
  const printable = cmds.map((a) => ["reg", ...a.map((x) => (/\s/.test(x) ? `"${x}"` : x))].join(" "));
  if (opts.dryRun) return printable;
  if (process.platform !== "win32") {
    throw new Error("register-filetype is Windows-only (use --dry-run to print the registry commands).");
  }
  for (const a of cmds) {
    try {
      execFileSync("reg.exe", a, { stdio: "pipe" });
    } catch (e: any) {
      // Unregistering something that was never registered is fine.
      if (!opts.unregister) throw e;
    }
  }
  return printable;
}
